import{_ as t,a as o,o as r,a4 as a}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse('{"title":"Cart Rules","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-api/admin/marketing/promotions/cart-rules/index.md","filePath":"api/rest-api/admin/marketing/promotions/cart-rules/index.md","lastUpdated":1783420618000}'),d={name:"api/rest-api/admin/marketing/promotions/cart-rules/index.md"};function n(i,e,c,s,l,p){return r(),o("div",null,e[0]||(e[0]=[a('<h1 id="cart-rules" tabindex="-1">Cart Rules <a class="header-anchor" href="#cart-rules" aria-label="Permalink to &quot;Cart Rules&quot;">​</a></h1><p>A <strong>cart rule</strong> discounts the shopper&#39;s <strong>cart at checkout</strong> — unlike a catalog rule, which lowers a product&#39;s price before it is ever added to a cart. A cart rule can apply automatically when its conditions match, or be gated behind a coupon code. It mirrors the admin <strong>Marketing → Promotions → Cart Rules</strong> screen.</p><h2 id="how-a-cart-rule-works" tabindex="-1">How a cart rule works <a class="header-anchor" href="#how-a-cart-rule-works" aria-label="Permalink to &quot;How a cart rule works&quot;">​</a></h2><p>A rule has four parts: <strong>who it applies to</strong>, <strong>when it applies</strong>, <strong>how it is triggered</strong>, and <strong>what it does to the cart</strong>.</p><ul><li><strong>Who</strong> — <code>channels</code> (which storefront channels) and <code>customerGroups</code> (e.g. general, wholesale). A rule only fires for shoppers in a matching channel + group.</li><li><strong>When</strong> — an optional date window (<code>startsFrom</code> / <code>endsTill</code>, where <code>endsTill</code> must be <code>&gt;= startsFrom</code>) and a set of <code>conditions</code> (cart / product filters such as <em>subtotal ≥ 100</em> or <em>category = Summer</em>). <code>conditionType</code> decides whether <strong>all</strong> conditions must match (<code>1</code>) or <strong>any</strong> (<code>0</code>).</li><li><strong>How it is triggered</strong> — <code>couponType</code>:</li></ul><table tabindex="0"><thead><tr><th><code>couponType</code></th><th>Trigger</th></tr></thead><tbody><tr><td><code>0</code></td><td>Auto-apply — the rule fires automatically whenever its conditions match.</td></tr><tr><td><code>1</code></td><td>Specific code — the shopper must enter a coupon code. <code>couponCode</code> is the rule&#39;s primary code (required unless codes are auto-generated).</td></tr></tbody></table><p>When <code>couponType</code> is <code>1</code>, additional codes can be issued in bulk through <strong>Cart Rule Coupons</strong>.</p><ul><li><strong>What</strong> — the <code>actionType</code> + <code>discountAmount</code> rewrite the cart total:</li></ul><table tabindex="0"><thead><tr><th><code>actionType</code></th><th>Effect</th></tr></thead><tbody><tr><td><code>by_percent</code></td><td>Reduce the cart by N% (<code>discountAmount</code> capped at <code>100</code>)</td></tr><tr><td><code>by_fixed</code></td><td>Reduce each matching item by a fixed amount</td></tr><tr><td><code>cart_fixed</code></td><td>Reduce the whole cart by a fixed amount</td></tr><tr><td><code>buy_x_get_y</code></td><td>Buy-X-get-Y, driven by <code>discountQuantity</code> and <code>discountStep</code></td></tr></tbody></table><p><code>freeShipping</code> (<code>1</code>) grants free shipping; <code>applyToShipping</code> (<code>1</code>) also applies the discount to the shipping cost.</p><p><strong>Priority and stacking.</strong> <code>sortOrder</code> sets evaluation priority (lower runs first). <code>endOtherRules</code> (<code>1</code>) stops any lower-priority rule from also applying once this one matches.</p><p><strong>Status and usage.</strong> <code>status</code> (<code>0</code>/<code>1</code>) toggles the rule on. <code>usagePerCustomer</code> and <code>usesPerCoupon</code> cap how often it can be used (<code>0</code> = unlimited). <code>timesUsed</code> records how often the rule has applied and is read-only.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Endpoint</th></tr></thead><tbody><tr><td><a href="/api/rest-api/admin/marketing/promotions/cart-rules-list.html">List</a></td><td><code>GET /api/admin/marketing/cart-rules</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/cart-rules-detail.html">Detail</a></td><td><code>GET /api/admin/marketing/cart-rules/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/cart-rules-create.html">Create</a></td><td><code>POST /api/admin/marketing/cart-rules</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/cart-rules-update.html">Update</a></td><td><code>PUT /api/admin/marketing/cart-rules/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/cart-rules-copy.html">Copy</a></td><td><code>POST /api/admin/marketing/cart-rules/{id}/copy</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/cart-rules-delete.html">Delete</a></td><td><code>DELETE /api/admin/marketing/cart-rules/{id}</code></td></tr><tr><td><a href="/api/rest-api/admin/marketing/promotions/cart-rules-mass-delete.html">Mass Delete</a></td><td><code>POST /api/admin/marketing/cart-rules/mass-delete</code></td></tr></tbody></table><p><code>conditions</code>, <code>channels</code>, and <code>customerGroups</code> are returned only on the <strong>detail</strong> endpoint — they are <code>null</code> on list rows. List rows do carry <code>couponCode</code>.</p><p>Coupon-gated rules (<code>couponType</code> = <code>1</code>) draw their codes from <strong>Cart Rule Coupons</strong>, a sub-resource of each cart rule.</p><p>All Cart Rules endpoints require an admin Bearer token — see <a href="/api/rest-api/admin/authentication.html">Authentication</a>.</p>',17)]))}const m=t(d,[["render",n]]);export{h as __pageData,m as default};
